using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class DetailInventory {
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 public static object Run(){var s=SceneManager.GetActiveScene();var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var center=new Vector3(-15,-82,-10);
 var lights=root.GetComponentsInChildren<Light>().Where(l=>Vector3.Distance(l.transform.position,center)<14).Select(l=>new{path=PathOf(l.transform),pos=l.transform.position.ToString("F3"),l.type,l.intensity,l.range,l.spotAngle,l.shadows}).ToArray();
 var stations=root.Find("C01_Experiment_Art/C01_Clinical_Stations").Cast<Transform>().Select(t=>new{path=PathOf(t),local=t.localPosition.ToString("F3"),rot=t.localEulerAngles.ToString("F3"),colliders=t.GetComponentsInChildren<BoxCollider>().Where(c=>c.enabled).Select(c=>new{center=c.bounds.center.ToString("F3"),size=c.bounds.size.ToString("F3"),localcenter=c.center.ToString("F3"),localsize=c.size.ToString("F3")}),meshes=t.GetComponentsInChildren<MeshFilter>().Select(m=>new{m.name,path=AssetDatabase.GetAssetPath(m.sharedMesh),bounds=m.GetComponent<Renderer>().bounds.ToString()})}).ToArray();
 var nearby=root.GetComponentsInChildren<Renderer>().Where(r=>Vector3.Distance(r.bounds.center,center)<12&&r.sharedMaterials.Any(m=>m&&m.IsKeywordEnabled("_EMISSION"))).Select(r=>new{path=PathOf(r.transform),center=r.bounds.center.ToString("F3"),materials=r.sharedMaterials.Where(m=>m&&m.IsKeywordEnabled("_EMISSION")).Select(m=>new{m.name,path=AssetDatabase.GetAssetPath(m),emission=m.HasProperty("_EmissionColor")?m.GetColor("_EmissionColor").ToString():""})}).ToArray();
 var doors=root.Find("Pocket_Doors_Open").Cast<Transform>().Where(t=>Vector3.Distance(t.position,center)<12).Select(t=>new{path=PathOf(t),pos=t.position.ToString("F3"),rot=t.eulerAngles.ToString("F3"),meshes=t.GetComponentsInChildren<MeshFilter>().Select(m=>new{m.name,bounds=m.GetComponent<Renderer>().bounds.ToString()})}).ToArray();
 var result=new{s.isDirty,lights,stations,nearby,doors};var o=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/C01_Finish/details_inventory.json"));File.WriteAllText(o,JsonConvert.SerializeObject(result,Formatting.Indented));return new{file=o,lights=lights.Length,stations=stations.Length,doors=doors.Length};}
}
